# This code has been fully generated by an AI.
#
# Category coverage: dry-run conformance across all plugin categories and all 46 first-party plugins (Issue #349).
set -euo pipefail
source "$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)/../../scripts/common.sh"

export GOTOOLCHAIN="${GOTOOLCHAIN:-go1.26.10}"
SEMREL_E2E_REBUILD=1 build_semrel

COND_GHA=$(SEMREL_E2E_REBUILD=1 build_plugin condition-github-actions condition-github-actions)
ANALYZER_CONV=$(SEMREL_E2E_REBUILD=1 build_plugin analyzer-conventional analyzer-conventional)
GEN_NOTES=$(SEMREL_E2E_REBUILD=1 build_plugin generator-release-notes generator-release-notes)
GEN_MD=$(SEMREL_E2E_REBUILD=1 build_plugin generator-changelog-md generator-changelog-md)
UPD_NPM=$(SEMREL_E2E_REBUILD=1 build_plugin updater-npm updater-npm)
UPD_CARGO=$(SEMREL_E2E_REBUILD=1 build_plugin updater-cargo updater-cargo)
PUB_NPM=$(SEMREL_E2E_REBUILD=1 build_plugin publisher-npm publisher-npm)
PROV_GH=$(SEMREL_E2E_REBUILD=1 build_plugin provider-github provider-github)
HOOK_SLACK=$(SEMREL_E2E_REBUILD=1 build_plugin hook-slack hook-slack)

REPO=$(new_scenario_repo "27-dry-run-conformance")

cat > "$REPO/package.json" <<'EOF'
{
  "name": "dry-run-demo",
  "version": "0.1.0"
}
EOF

cat > "$REPO/Cargo.toml" <<'EOF'
[package]
name = "dry-run-demo"
version = "0.1.0"
edition = "2021"
EOF

cat > "$REPO/.semrel.yaml" <<EOF
schemaVersion: 1
tagPrefix: "v"
branches:
  - name: main
rules:
  - type: feat
    bump: minor
  - type: fix
    bump: patch
plugins:
  - name: condition-github-actions
    path: "$COND_GHA"
    phase: condition
  - name: analyzer-conventional
    path: "$ANALYZER_CONV"
    phase: analyzer
  - name: generator-release-notes
    path: "$GEN_NOTES"
    phase: generator
  - name: updater-npm
    path: "$UPD_NPM"
    phase: pre-tag
    args:
      file: package.json
  - name: updater-cargo
    path: "$UPD_CARGO"
    phase: pre-tag
    args:
      file: Cargo.toml
  - name: generator-changelog-md
    path: "$GEN_MD"
    phase: pre-tag
  - name: publisher-npm
    path: "$PUB_NPM"
    phase: release
  - name: provider-github
    path: "$PROV_GH"
    phase: release
    args:
      owner: SemRels
      repo: semrel
  - name: hook-slack
    path: "$HOOK_SLACK"
    phase: release
    args:
      webhook_url: "https://hooks.slack.com/services/T00000000/B00000000/SUPERSECRETTOKEN12345"
EOF

commit_all "$REPO" "chore: initial commit"
git -C "$REPO" tag v0.1.0

echo "feature" > "$REPO/feature.txt"
commit_all "$REPO" "feat: add dry-run conformance feature"

OUT_TXT="$WORK_DIR/27-stdout.txt"
ERR_TXT="$WORK_DIR/27-stderr.txt"
OUT_JSON="$WORK_DIR/27-output.json"

( cd "$REPO" && env -u GITHUB_ACTIONS -u GITHUB_TOKEN -u GH_TOKEN -u NPM_TOKEN "$SEMREL_BIN" release --dry-run --config .semrel.yaml >"$OUT_TXT" 2>"$ERR_TXT" )

assert_tag_absent "$REPO" "v0.2.0"
assert_file_contains "$REPO/package.json" '"version": "0.1.0"'
assert_file_contains "$REPO/Cargo.toml" 'version = "0.1.0"'

if [[ -z "$(git -C "$REPO" status --porcelain)" ]]; then
  ok "git status --porcelain is clean after dry-run"
else
  fail "git working tree was modified during dry-run: $(git -C "$REPO" status --porcelain)"
fi

assert_file_contains "$OUT_TXT" "── \[dry-run\] updater-npm (pre-tag) ──"
assert_file_contains "$OUT_TXT" "--- a/package.json"
assert_file_contains "$OUT_TXT" "+++ b/package.json"
assert_file_contains "$OUT_TXT" "--- a/Cargo.toml"
assert_file_contains "$OUT_TXT" "+++ b/Cargo.toml"
assert_file_contains "$OUT_TXT" "## What's Changed"
assert_file_contains "$OUT_TXT" "decision: block"
assert_file_not_contains "$OUT_TXT" "SUPERSECRETTOKEN12345"
assert_file_not_contains "$ERR_TXT" "SUPERSECRETTOKEN12345"
assert_file_contains "$ERR_TXT" "\[dry-run\]"

( cd "$REPO" && env -u GITHUB_ACTIONS -u GITHUB_TOKEN -u GH_TOKEN -u NPM_TOKEN "$SEMREL_BIN" release --dry-run --output json --config .semrel.yaml >"$OUT_JSON" 2>/dev/null )

assert_file_contains "$OUT_JSON" '"dry_run": true'
assert_file_contains "$OUT_JSON" '"dry_run_plugins":'
assert_file_contains "$OUT_JSON" '"dry_run_supported": true'

# Verify all 46 first-party plugins + plugin-template declare x-semrel-dry-run in schema/v1.json
ALL_PLUGINS=(
  analyzer-conventional analyzer-default
  condition-bitbucket-pipelines condition-circleci condition-generic
  condition-gitea-actions condition-github-actions condition-gitlab-ci
  generator-changelog-html generator-changelog-md generator-release-notes
  hook-discord hook-email hook-exec hook-gitplugin hook-jira hook-matrix hook-slack hook-teams
  packager-nfpm plugin-template
  provider-bitbucket provider-git provider-gitea provider-github provider-gitlab
  publisher-crates publisher-docker publisher-generic-http publisher-npm publisher-oci publisher-pypi
  updater-cargo updater-composer updater-docker updater-go updater-gradle updater-helm
  updater-homebrew updater-maven updater-npm updater-nuget updater-pubspec updater-python
  updater-replace updater-terraform updater-zig
)

for p in "${ALL_PLUGINS[@]}"; do
  pdir="$WORKSPACE_ROOT/$p"
  if [[ ! -d "$pdir" ]]; then
    continue
  fi
  if [[ -f "$pdir/schema/v1.json" ]] && grep -q '"x-semrel-dry-run"[[:space:]]*:[[:space:]]*true' "$pdir/schema/v1.json"; then
    ok "$p/schema/v1.json declares x-semrel-dry-run: true"
  else
    fail "$p/schema/v1.json is missing x-semrel-dry-run: true"
  fi
done

finish
